mapper.select:
SELECT  a.*,b.BID_PRICE as bidPrice
FROM BIZ_PROJECT a left join BIZ_CRM_BIDOPEN  b on a.ID = b.PROJECT_ID and b.DELETE_FLAG = 'NOT_DELETE'
    ${ew.customSqlSegment}

SELECT  a.*,b.BID_PRICE as bidPrice
FROM BIZ_PROJECT a left join BIZ_CRM_BIDOPEN  b on a.ID = b.PROJECT_ID and b.DELETE_FLAG = 'NOT_DELETE'
where a.ID = #{id}

SELECT  a.*,b.SUM_AMOUNT as htSumAmount
FROM BIZ_PROJECT a left join BIZ_CRM_HETONG  b on a.ID = b.BIZ_PROJECT_ID and b.DELETE_FLAG = 'NOT_DELETE' and b.STATUS = '1'
    ${ew.customSqlSegment}
